<!doctype html><html><head><meta charset="utf-8"><title>Job Application Form</title><style>body{font:11px Arial;margin:0;padding:15px}.form{max-width:800px;margin:auto}.section{border:2px solid #000;margin-bottom:5px;padding:8px}.photo{float:right;width:70px;height:90px;border:1px solid #000;text-align:center}.main{margin-right:85px}.row{margin:6px 0}.label{font-weight:bold;font-size:10px}.line{border:0;border-bottom:1px solid #000;background:none}.tbl{width:100%;border-collapse:collapse;margin-top:5px}.tbl th,.tbl td{border:1px solid #000;padding:3px;text-align:center;font-size:9px}.tbl th{background:#f0f0f0}.title{font-weight:bold;font-size:12px;margin-bottom:5px}.sign{display:flex;justify-content:space-between;margin-top:20px}@media print{body{padding:10px}}</style></head><body><div class="form"><div class="section"><div style="text-align:center;font-weight:bold">PLEASE ANSWER EACH CLEARLY AND COMPLETELY. THE INFORMATION PROVIDED IN THIS<br>APPLICATION FORM WILL BE KEPT PRIVATE AND CONFIDENTIAL.</div><div class="photo">@if($application->photograph)<img src="{{asset('uploads/job_photos/'.$application->photograph)}}" style="width:66px;height:86px;object-fit:cover">@else AFFIX<br>RECENT<br>PHOTOGRAPH<br>HERE @endif</div><div class="main">@foreach([['1. Full Name','full_name'],["2. Father's/Husband Name",'father_husband_name'],['3. CNIC No.','cnic'],['4. Position Applied','position_applied'],['5. Min Salary Acceptable','min_salary_acceptable'],['6. Nationality','nationality'],['7. Religion','religion'],['8. Gender','gender'],['9. Height Ft','height_ft'],['9. Height Inches','height_inches'],['10. Weight Kg','weight_kg'],['13. Marital Status','marital_status'],['11. Date of Birth','date_of_birth'],['12. Place of Birth','place_of_birth'],['15. Contact No(s)','contact_numbers']] as [$label,$key])<div class="row"><span class="label">{{$label}}:</span> <input class="line" value="{{ $key==='date_of_birth' ? $application->{$key}?->format('d/m/Y') : $application->{$key} }}" r